from taf.fdsw.rc.interfaces.FDSW21A.fdsw import FDSW21A


class FDSW21B(FDSW21A):
    VERSION_NAME = 'FDSW21B'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW21B, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                      secure=secure)
